{
  "$schema": "../schemas/pattern.schema.json",
  "id": "pattern.page-layout",
  "name": "Page layout",
  "purpose": "業務オブジェクトの関係、重要度、主要操作を、画面をまたいで予測できる順序で配置する",
  "principles": [
    {
      "id": "predictable-order",
      "title": "読む順序を固定する",
      "description": "アプリケーションヘッダー、戻るナビゲーション、ページ見出し、補助ナビゲーション、コンテンツの順に配置する"
    },
    {
      "id": "object-first",
      "title": "業務オブジェクトを起点に選ぶ",
      "description": "一覧、詳細、設定などの画面名ではなく、利用者が比較・確認・切り替えたい対象の関係からvariantを選ぶ"
    },
    {
      "id": "one-primary-action",
      "title": "主要操作を一つに絞る",
      "description": "見出し領域に置く強い操作は一つとし、補助操作は同列に強調しない"
    }
  ],
  "anatomy": [
    {
      "id": "app-header",
      "name": "アプリケーションヘッダー",
      "required": true,
      "description": "サービス全体の移動と利用者コンテキストを提供する"
    },
    {
      "id": "back-navigation",
      "name": "戻るナビゲーション",
      "required": false,
      "description": "親の一覧や上位ビューへ戻る経路がある詳細画面では、ページ見出しの前に配置する"
    },
    {
      "id": "page-heading",
      "name": "ページ見出し",
      "required": true,
      "description": "画面タイトル、短いリード文、状態、主要操作をまとめる"
    },
    {
      "id": "local-navigation",
      "name": "補助ナビゲーション",
      "required": false,
      "description": "同じ業務オブジェクト内で頻繁に表示を切り替える場合だけ追加する"
    },
    {
      "id": "content",
      "name": "コンテンツ領域",
      "required": true,
      "description": "情報をセクションへ分け、重要度の高い順に配置する"
    },
    {
      "id": "feedback",
      "name": "フィードバック領域",
      "required": false,
      "description": "読み込み、空、失敗、権限制限を操作対象の近くに表示する"
    }
  ],
  "variants": [
    {
      "id": "collection-table",
      "name": "一覧（テーブル）",
      "useWhen": "複数のオブジェクトを属性で比較しながら探す",
      "avoidWhen": "項目数が少ない、または狭い画面での利用が中心",
      "structure": ["ページ見出し", "一覧操作Toolbar", "テーブル", "ページネーション"],
      "desktop": "コンテンツ幅を広く使い、比較に必要な列を優先して表示する",
      "narrow": "一覧（リスト）へ切り替え、主要属性以外は詳細画面へ移す",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [
          ".page-shell",
          ".page-shell--stack",
          ".page-heading",
          ".collection-region",
          ".collection-toolbar",
          ".search-field",
          ".collection-table-wrap",
          ".collection-list-mobile"
        ],
        "values": {
          "maxWidth": "content.maxWidth",
          "pagePaddingBlock": "space.8",
          "toolbarGapBeforeTable": "space.3",
          "headingToCollectionGap": "space.6",
          "searchDesktopWidth": "16rem",
          "searchNarrowWidth": "100%"
        }
      }
    },
    {
      "id": "collection-list",
      "name": "一覧（リスト）",
      "useWhen": "狭い領域でオブジェクトの識別情報と状態を順番に確認する",
      "avoidWhen": "複数列を横断して比較することが主要タスク",
      "structure": ["ページ見出し", "検索・絞り込み", "リスト", "追加読み込み"],
      "desktop": "短い一覧や補助領域で使用し、必要以上にカード化しない",
      "narrow": "1行に識別情報、状態、主要操作を置き、詳細は次画面に分ける",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [
          ".collection-list-mobile",
          ".collection-list-mobile__content",
          ".collection-list-mobile__link",
          ".collection-list-mobile__meta"
        ],
        "values": {
          "itemGap": "space.4",
          "contentGap": "space.3"
        }
      }
    },
    {
      "id": "single-one-column",
      "name": "詳細（1カラム）",
      "useWhen": "一つのオブジェクトを、並列な情報セクションに分けて確認・操作する",
      "avoidWhen": "主情報と副情報の重要度や情報量に大きな差がある",
      "structure": ["戻るナビゲーション", "ページ見出し", "概要", "詳細セクション", "関連オブジェクト"],
      "desktop": "最大1200pxの中で、セクションを重要度順に縦へ配置する",
      "narrow": "モバイルでは1カラムに積み替える",
      "layout": {
        "breakpoint": "breakpoint.narrow",
        "classes": [
          ".page-shell",
          ".page-shell--stack",
          ".detail-page__heading",
          ".page-heading",
          ".detail-grid",
          ".detail-content"
        ],
        "values": {
          "maxWidth": "content.maxWidth",
          "backNavigationGap": "space.4",
          "headingToContentGap": "space.8",
          "sectionGap": "space.6",
          "groupGap": "space.4"
        }
      }
    },
    {
      "id": "single-two-column",
      "name": "詳細（2カラム）",
      "useWhen": "主情報を操作しながら、識別情報や履歴などの副情報を参照する",
      "avoidWhen": "二つの領域が同じ重要度、または狭い画面で同時表示する必要がない",
      "structure": ["戻るナビゲーション", "ページ見出し", "副情報", "主情報"],
      "desktop": "主情報を副情報の2倍以上の幅にする",
      "narrow": "利用者が先に確認する情報から1カラムに積む"
    },
    {
      "id": "side-navigation",
      "name": "サイドナビゲーション＋コンテンツ",
      "useWhen": "設定項目が多い、階層がある、または項目間を頻繁に移動する",
      "avoidWhen": "ナビゲーションが少なく、ページ見出し内の切り替えで足りる",
      "structure": ["ページ見出し", "サイドナビゲーション", "選択中のコンテンツ"],
      "desktop": "ナビゲーション幅を固定し、コンテンツへ残りの幅を割り当てる",
      "narrow": "ナビゲーションを別画面または上部の切り替えへ移す"
    },
    {
      "id": "collection-detail",
      "name": "一覧＋詳細",
      "useWhen": "一覧の選択対象を頻繁に切り替えながら詳細を確認する",
      "avoidWhen": "詳細の編集が複雑、または一覧へ戻る頻度が低い",
      "structure": ["ページ見出し", "オブジェクト一覧", "選択中の詳細"],
      "desktop": "一覧領域を固定し、詳細領域へ十分な作業幅を確保する",
      "narrow": "一覧と詳細を二つのページに分ける"
    }
  ],
  "states": ["loading", "empty", "error", "permission-limited"],
  "components": [
    "component.button",
    "component.link",
    "component.table",
    "component.toolbar",
